float clamp01(float x) { return clamp(x, 0.0, 1.0); }
vec2 clamp01(vec2 x) { return clamp(x, vec2(0.0), vec2(1.0)); }
vec3 clamp01(vec3 x) { return clamp(x, vec3(0.0), vec3(1.0)); }
vec4 clamp01(vec4 x) { return clamp(x, vec4(0.0), vec4(1.0)); }

// Texture helper functions
vec4 GetPixel(vec2 uv) { return texture(sampler_main, uv); }
vec4 GetBlur1(vec2 uv) { return texture(sampler_blur1, uv); }
vec4 GetBlur2(vec2 uv) { return texture(sampler_blur2, uv); }
vec4 GetBlur3(vec2 uv) { return texture(sampler_blur3, uv); }


void main() {
  vec4 ret = vec4(0.0);
  vec2 uv = vUv;
  float rad = vRadius;

    // sample previous uFrame
    vec2 muv;
    muv.x = vUv.x-((.01*cos(vUv.x*(5+2*audioLowSmooth)+uTime))+(.01*cos(vUv.y*(5+2*audioLowSmooth)+uTime)))*.5*audioHighSmooth;
    muv.y = vUv.y+((.01*sin(vUv.x*(5+2*audioMidSmooth)+uTime))-(.01*cos(vUv.y*(5+2*audioMidSmooth)+uTime)))*.5*audioLowSmooth;
    vec3 blur1 = GetBlur2(muv);
    ret = texture( sampler_pw_main, muv ).xyz;
    ret.x = ret.x+(blur1.x)*(audioLowSmooth*.05);
    ret.y = ret.y+(blur1.y)*(audioHighSmooth*.05);
    ret.z = ret.z+(blur1.z)*(audioMidSmooth*.05);
    if(ret.x > .9){
      ret.x = 0;
    }
    if(ret.y > .9){
      ret.y = 0;
    }
    if(ret.z > .9){
      ret.z = 0;
    }

  fragColor = ret;
}

